var L_note_navigator_js=globalThis.I18n||{t:(s,v)=>v?s.replace(/\{(\w+)\}/g,(m,k)=>v[k]??m):s,error:s=>s,locale:undefined};
/* Book-scoped note navigation. Thumbnails are transient and contain visible strokes only. */
(function(root){
 const E=id=>document.getElementById(id),paper={transparent:'#f0f0ea',white:'#ffffff',yellow:'#fff0ae',red:'#f9dad6',green:'#daeedc',blue:'#dce9fa'};let listPage=1,jumping=false;
 const normalize=t=>String(t||'').normalize('NFKC').replace(/\s+/gu,'').toLocaleLowerCase();
 function selectedRows(){const q=normalize(E('noteSearch').value),type=E('noteTypeFilter').value;return Notes.records().sort((a,b)=>(Notes.pageNumber(a)||Infinity)-(Notes.pageNumber(b)||Infinity)||(a.createdAt||0)-(b.createdAt||0)||a.id.localeCompare(b.id)).filter(m=>(type==='all'||(m.type==='drawing'?'drawing':'text')===type)&&(!q||m.type!=='drawing'&&!Notes.masked(m)&&normalize(m.text).includes(q)))}
 function changed(){if(!E('noteNavigator').open)return;const rows=selectedRows(),size=AppSettings.read().notePageSize||15,pages=Math.max(1,Math.ceil(rows.length/size));listPage=Math.max(1,Math.min(listPage,pages));const list=E('noteList');list.replaceChildren();E('noteListCount').textContent=rows.length+L_note_navigator_js.t("개");E('noteListPage').textContent=listPage+' / '+pages;E('noteListPrev').disabled=listPage===1;E('noteListNext').disabled=listPage===pages;
 for(const m of rows.slice((listPage-1)*size,listPage*size)){const drawing=m.type==='drawing',masked=Notes.masked(m),n=Notes.pageNumber(m),row=document.createElement('article'),meta=document.createElement('div');row.className='highlight-list-item note-list-item';meta.className='highlight-list-meta';meta.textContent=(drawing?L_note_navigator_js.t("그리기"):L_note_navigator_js.t("텍스트"))+' · '+(n?n+L_note_navigator_js.t("페이지"):L_note_navigator_js.t("위치 확인 필요"));const go=document.createElement('button');go.type='button';go.className=drawing&&!masked?'note-list-go note-list-drawing':'note-list-go';go.disabled=jumping||!n;
 if(masked)go.textContent=L_note_navigator_js.t("학습 시트로 숨김");else if(drawing){const ratio=Math.max(.01,(m.layout==='page'?m.pageSize.height/m.pageSize.width:(m.height||m.width*.6)/m.width)),w=Math.min(320,132/ratio),h=w*ratio,c=document.createElement('canvas');c.width=Math.max(1,Math.round(w*2));c.height=Math.max(1,Math.round(h*2));c.style.width=w+'px';c.style.height=h+'px';c.style.background=paper[m.background]||paper.transparent;c.setAttribute('aria-hidden','true');NoteDrawing.paint(c,m.strokes,Notes.hiddenColor);go.setAttribute('aria-label',(n?n+L_note_navigator_js.t("페이지 "):'')+L_note_navigator_js.t("그리기 메모로 이동"));go.append(c)}else{const content=document.createElement('span');content.className='note-list-text';content.textContent=m.text;go.append(content)}
 go.onclick=async()=>{if(jumping)return;jumping=true;E('noteNavigator').close();try{await Notes.position(m.id)}catch(e){SettingsUI.toast(L_note_navigator_js.error(e.message))}finally{jumping=false}};row.append(meta,go);list.append(row)}
 if(!rows.length){const p=document.createElement('p');p.className='note-list-empty';p.textContent=E('noteSearch').value?L_note_navigator_js.t("검색 결과가 없습니다. 텍스트 메모의 내용만 검색합니다."):E('noteTypeFilter').value==='all'?L_note_navigator_js.t("저장한 메모가 없습니다."):L_note_navigator_js.t("해당 종류의 메모가 없습니다.");list.append(p)}}
 function open(event){event?.preventDefault();event?.stopPropagation();if(Notes.isReady?.()===false){SettingsUI.toast(L_note_navigator_js.t("메모 저장소를 준비한 뒤 다시 시도하세요."));return}if(busy||Notes.isActive()||BetaTranslation.isActive()){SettingsUI.toast(L_note_navigator_js.t("현재 편집·인식 작업을 저장하거나 취소한 뒤 탐색기를 여세요."));return}root.HighlightNavigator?.pause();ReaderSelection.invalidate('');listPage=1;E('noteSearch').value='';E('noteTypeFilter').value='all';E('noteNavigator').showModal();changed();E('noteSearch').focus()}
 E('noteCount').onclick=open;E('noteNavigatorClose').onclick=()=>E('noteNavigator').close();E('noteSearch').oninput=()=>{listPage=1;changed()};E('noteTypeFilter').onchange=()=>{listPage=1;changed()};E('noteListPrev').onclick=()=>{listPage--;changed()};E('noteListNext').onclick=()=>{listPage++;changed()};root.NoteNavigator={changed,bookChanged(){E('noteNavigator').close();E('noteList').replaceChildren();E('noteSearch').value='';listPage=1}};
})(globalThis);
